// Limit to 5 contacts per run to keep AI costs low
const allContacts = $input.all();

// Only process contacts with email OR LinkedIn
const validContacts = allContacts.filter(contact => {
  const data = contact.json;
  const hasEmail = data.email || data['Email'];
  const hasLinkedIn = data.linkedinUrl || data['LinkedIn URL'];
  return hasEmail || hasLinkedIn;
});

// Limit to first 5
const limitedContacts = validContacts.slice(0, 5);

return limitedContacts;
